window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-32422ad4e74c2ba1"]={"versions": [{"id": "FIG-32422ad4e74c2ba1", "releases": ["R2.1.20", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm der AUTOSAR Classic Platform zur Darstellung des Zusammenspiels zwischen einer Software-Komponente, der Runtime Environment (RTE), dem NVRAM Manager (NvM) sowie Basissoftware-Komponenten und den zugehörigen RAM-Spiegelblöcken (Mirror RAM blocks) beim expliziten Lesen und Schreiben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR SW-Component</strong>: Anwendungskomponente oberhalb der RTE, agiert als Client für explizite NVRAM-Operationen und greift direkt auf Anwendungs-RAM-Blöcke zu.</li>\n<li><strong>RTE</strong>: Runtime Environment, gestrichelt als Vermittlungsschicht für Client-Server- bzw. Service-Interaktionen zwischen SW-Komponente und Basissoftware dargestellt.</li>\n<li><strong>NVRAM Manager</strong>: Zentrales Basissoftware-Modul (Memory Services) zur Verwaltung und Durchführung von Lese- und Schreiboperationen auf nicht-flüchtige Medien.</li>\n<li><strong>Other parts of basic SW</strong>: Weitere Basissoftware-Module (z. B. ECU State Manager), angebunden über eine Initialisierungsschnittstelle („Initialize“) an den NVRAM Manager.</li>\n<li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM Mirror Blocks), auf die sowohl die SW-Komponente als auch der NVRAM Manager zugreifen.</li>\n<li><strong>Schnittstellen / Interaktionspfade</strong>:</li>\n<li>Unidirektionaler Pfeil von SW-Component nach unten zum NVRAM Manager via RTE (Anforderung zum Speichern/Wiederherstellen, am linken Bildrand abgeschnitten).</li>\n<li>Unidirektionaler Pfeil vom NVRAM Manager nach oben zur SW-Component via RTE („Notify on outcome of request (optional)“).</li>\n<li>Unidirektionaler Pfeil von SW-Component zu den RAM blocks („Access content of RAM blocks“).</li>\n<li>Unidirektionaler Pfeil von Other parts of basic SW zum NVRAM Manager („Initialize“).</li>\n<li>Unidirektionaler Doppelpfeil / Diagonale Verbindung vom NVRAM Manager zu den RAM blocks („Restore/save block from/to non-volatile medium“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung</strong>: Vorab-Initialisierung des NVRAM Managers durch andere Basissoftware-Module über „Initialize“.</li>\n<li><strong>Anforderungsübermittlung</strong>: Die AUTOSAR SW-Component sendet über die RTE eine explizite Anforderung zum Sichern oder Wiederherstellen eines Speicherblocks an den NVRAM Manager.</li>\n<li><strong>NVRAM-Manager-Operation</strong>: Der NVRAM Manager führt die Datenübertragung zwischen den RAM-Blöcken und dem nicht-flüchtigen Medium durch („Restore/save block from/to non-volatile medium“).</li>\n<li><strong>Ergebnisbenachrichtigung</strong>: Optional benachrichtigt der NVRAM Manager die SW-Component über die RTE über das Ergebnis der Operation („Notify on outcome of request (optional)“).</li>\n<li><strong>Datenzugriff</strong>: Die AUTOSAR SW-Component greift unabhängig von der NVRAM-Manager-Direktkommunikation direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Entkopplung</strong>: Die Datenübertragung zwischen NVRAM Manager und SW-Component erfolgt nicht über direkte Parameter der Service-Kommunikation, sondern über die dedizierten RAM-Blöcke (RAM Mirror).</li>\n<li><strong>Synchronisation & Exklusivität</strong>: Während der expliziten Übertragungsphase darf die SW-Component nicht konkurrierend auf den betreffenden RAM-Block zugreifen, bis die Operation abgeschlossen ist.</li>\n<li><strong>Konfigurationsverträge</strong>: Zwischen SW-Component und NVRAM Manager müssen Eigenschaften wie Blockgröße, Identifikation und Zugriffsrechte konsistent konfiguriert sein.</li>\n</ul>"}, {"id": "FIG-440c8e5a15bd4362", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm der AUTOSAR Classic Platform zur Darstellung des Zusammenspiels zwischen einer Software-Komponente, der Runtime Environment (RTE), dem NVRAM Manager (NvM) sowie Basissoftware-Komponenten und den zugehörigen RAM-Spiegelblöcken (Mirror RAM blocks) beim expliziten Lesen und Schreiben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR SW-Component</strong>: Anwendungskomponente oberhalb der RTE, agiert als Client für explizite NVRAM-Operationen und greift direkt auf Anwendungs-RAM-Blöcke zu.</li>\n<li><strong>RTE</strong>: Runtime Environment, gestrichelt als Vermittlungsschicht für Client-Server- bzw. Service-Interaktionen zwischen SW-Komponente und Basissoftware dargestellt.</li>\n<li><strong>NVRAM Manager</strong>: Zentrales Basissoftware-Modul (Memory Services) zur Verwaltung und Durchführung von Lese- und Schreiboperationen auf nicht-flüchtige Medien.</li>\n<li><strong>Other parts of basic SW</strong>: Weitere Basissoftware-Module (z. B. ECU State Manager), angebunden über eine Initialisierungsschnittstelle („Initialize“) an den NVRAM Manager.</li>\n<li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM Mirror Blocks), auf die sowohl die SW-Komponente als auch der NVRAM Manager zugreifen.</li>\n<li><strong>Schnittstellen / Interaktionspfade</strong>:</li>\n<li>Unidirektionaler Pfeil von SW-Component nach unten zum NVRAM Manager via RTE (Anforderung zum Speichern/Wiederherstellen, am linken Bildrand abgeschnitten).</li>\n<li>Unidirektionaler Pfeil vom NVRAM Manager nach oben zur SW-Component via RTE („Notify on outcome of request (optional)“).</li>\n<li>Unidirektionaler Pfeil von SW-Component zu den RAM blocks („Access content of RAM blocks“).</li>\n<li>Unidirektionaler Pfeil von Other parts of basic SW zum NVRAM Manager („Initialize“).</li>\n<li>Unidirektionaler Doppelpfeil / Diagonale Verbindung vom NVRAM Manager zu den RAM blocks („Restore/save block from/to non-volatile medium“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung</strong>: Vorab-Initialisierung des NVRAM Managers durch andere Basissoftware-Module über „Initialize“.</li>\n<li><strong>Anforderungsübermittlung</strong>: Die AUTOSAR SW-Component sendet über die RTE eine explizite Anforderung zum Sichern oder Wiederherstellen eines Speicherblocks an den NVRAM Manager.</li>\n<li><strong>NVRAM-Manager-Operation</strong>: Der NVRAM Manager führt die Datenübertragung zwischen den RAM-Blöcken und dem nicht-flüchtigen Medium durch („Restore/save block from/to non-volatile medium“).</li>\n<li><strong>Ergebnisbenachrichtigung</strong>: Optional benachrichtigt der NVRAM Manager die SW-Component über die RTE über das Ergebnis der Operation („Notify on outcome of request (optional)“).</li>\n<li><strong>Datenzugriff</strong>: Die AUTOSAR SW-Component greift unabhängig von der NVRAM-Manager-Direktkommunikation direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Entkopplung</strong>: Die Datenübertragung zwischen NVRAM Manager und SW-Component erfolgt nicht über direkte Parameter der Service-Kommunikation, sondern über die dedizierten RAM-Blöcke (RAM Mirror).</li>\n<li><strong>Synchronisation & Exklusivität</strong>: Während der expliziten Übertragungsphase darf die SW-Component nicht konkurrierend auf den betreffenden RAM-Block zugreifen, bis die Operation abgeschlossen ist.</li>\n<li><strong>Konfigurationsverträge</strong>: Zwischen SW-Component und NVRAM Manager müssen Eigenschaften wie Blockgröße, Identifikation und Zugriffsrechte konsistent konfiguriert sein.</li>\n</ul>"}, {"id": "FIG-dc02ee2846558df6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm der AUTOSAR Classic Platform zur Darstellung des Zusammenspiels zwischen einer Software-Komponente, der Runtime Environment (RTE), dem NVRAM Manager (NvM) sowie Basissoftware-Komponenten und den zugehörigen RAM-Spiegelblöcken (Mirror RAM blocks) beim expliziten Lesen und Schreiben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR SW-Component</strong>: Anwendungskomponente oberhalb der RTE, agiert als Client für explizite NVRAM-Operationen und greift direkt auf Anwendungs-RAM-Blöcke zu.</li>\n<li><strong>RTE</strong>: Runtime Environment, gestrichelt als Vermittlungsschicht für Client-Server- bzw. Service-Interaktionen zwischen SW-Komponente und Basissoftware dargestellt.</li>\n<li><strong>NVRAM Manager</strong>: Zentrales Basissoftware-Modul (Memory Services) zur Verwaltung und Durchführung von Lese- und Schreiboperationen auf nicht-flüchtige Medien.</li>\n<li><strong>Other parts of basic SW</strong>: Weitere Basissoftware-Module (z. B. ECU State Manager), angebunden über eine Initialisierungsschnittstelle („Initialize“) an den NVRAM Manager.</li>\n<li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM Mirror Blocks), auf die sowohl die SW-Komponente als auch der NVRAM Manager zugreifen.</li>\n<li><strong>Schnittstellen / Interaktionspfade</strong>:</li>\n<li>Unidirektionaler Pfeil von SW-Component nach unten zum NVRAM Manager via RTE (Anforderung zum Speichern/Wiederherstellen, am linken Bildrand abgeschnitten).</li>\n<li>Unidirektionaler Pfeil vom NVRAM Manager nach oben zur SW-Component via RTE („Notify on outcome of request (optional)“).</li>\n<li>Unidirektionaler Pfeil von SW-Component zu den RAM blocks („Access content of RAM blocks“).</li>\n<li>Unidirektionaler Pfeil von Other parts of basic SW zum NVRAM Manager („Initialize“).</li>\n<li>Unidirektionaler Doppelpfeil / Diagonale Verbindung vom NVRAM Manager zu den RAM blocks („Restore/save block from/to non-volatile medium“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung</strong>: Vorab-Initialisierung des NVRAM Managers durch andere Basissoftware-Module über „Initialize“.</li>\n<li><strong>Anforderungsübermittlung</strong>: Die AUTOSAR SW-Component sendet über die RTE eine explizite Anforderung zum Sichern oder Wiederherstellen eines Speicherblocks an den NVRAM Manager.</li>\n<li><strong>NVRAM-Manager-Operation</strong>: Der NVRAM Manager führt die Datenübertragung zwischen den RAM-Blöcken und dem nicht-flüchtigen Medium durch („Restore/save block from/to non-volatile medium“).</li>\n<li><strong>Ergebnisbenachrichtigung</strong>: Optional benachrichtigt der NVRAM Manager die SW-Component über die RTE über das Ergebnis der Operation („Notify on outcome of request (optional)“).</li>\n<li><strong>Datenzugriff</strong>: Die AUTOSAR SW-Component greift unabhängig von der NVRAM-Manager-Direktkommunikation direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Entkopplung</strong>: Die Datenübertragung zwischen NVRAM Manager und SW-Component erfolgt nicht über direkte Parameter der Service-Kommunikation, sondern über die dedizierten RAM-Blöcke (RAM Mirror).</li>\n<li><strong>Synchronisation & Exklusivität</strong>: Während der expliziten Übertragungsphase darf die SW-Component nicht konkurrierend auf den betreffenden RAM-Block zugreifen, bis die Operation abgeschlossen ist.</li>\n<li><strong>Konfigurationsverträge</strong>: Zwischen SW-Component und NVRAM Manager müssen Eigenschaften wie Blockgröße, Identifikation und Zugriffsrechte konsistent konfiguriert sein.</li>\n</ul>"}, {"id": "FIG-d71d614e2e29f4e8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm der AUTOSAR Classic Platform zur Darstellung des Zusammenspiels zwischen einer Software-Komponente, der Runtime Environment (RTE), dem NVRAM Manager (NvM) sowie Basissoftware-Komponenten und den zugehörigen RAM-Spiegelblöcken (Mirror RAM blocks) beim expliziten Lesen und Schreiben.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR SW-Component</strong>: Anwendungskomponente oberhalb der RTE, agiert als Client für explizite NVRAM-Operationen und greift direkt auf Anwendungs-RAM-Blöcke zu.</li>\n<li><strong>RTE</strong>: Runtime Environment, gestrichelt als Vermittlungsschicht für Client-Server- bzw. Service-Interaktionen zwischen SW-Komponente und Basissoftware dargestellt.</li>\n<li><strong>NVRAM Manager</strong>: Zentrales Basissoftware-Modul (Memory Services) zur Verwaltung und Durchführung von Lese- und Schreiboperationen auf nicht-flüchtige Medien.</li>\n<li><strong>Other parts of basic SW</strong>: Weitere Basissoftware-Module (z. B. ECU State Manager), angebunden über eine Initialisierungsschnittstelle („Initialize“) an den NVRAM Manager.</li>\n<li><strong>RAM block</strong>: Gestapelte Speichereinheiten (RAM Mirror Blocks), auf die sowohl die SW-Komponente als auch der NVRAM Manager zugreifen.</li>\n<li><strong>Schnittstellen / Interaktionspfade</strong>:</li>\n<li>Unidirektionaler Pfeil von SW-Component nach unten zum NVRAM Manager via RTE mit vollständiger Beschriftung „Request to restore/save a block from/to non-volatile medium“.</li>\n<li>Unidirektionaler Pfeil vom NVRAM Manager nach oben zur SW-Component via RTE („Notify on outcome of request (optional)“).</li>\n<li>Unidirektionaler Pfeil von SW-Component zu den RAM blocks („Access content of RAM blocks“).</li>\n<li>Unidirektionaler Pfeil von Other parts of basic SW zum NVRAM Manager („Initialize“).</li>\n<li>Unidirektionaler Diagonaler Pfeil vom NVRAM Manager zu den RAM blocks („Restore/save block from/to non-volatile medium“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung</strong>: Vorab-Initialisierung des NVRAM Managers durch andere Basissoftware-Module über „Initialize“.</li>\n<li><strong>Anforderungsübermittlung</strong>: Die AUTOSAR SW-Component sendet über die RTE eine explizite Anforderung zum Sichern oder Wiederherstellen eines Speicherblocks an den NVRAM Manager.</li>\n<li><strong>NVRAM-Manager-Operation</strong>: Der NVRAM Manager führt die Datenübertragung zwischen den RAM-Blöcken und dem nicht-flüchtigen Medium durch („Restore/save block from/to non-volatile medium“).</li>\n<li><strong>Ergebnisbenachrichtigung</strong>: Optional benachrichtigt der NVRAM Manager die SW-Component über die RTE über das Ergebnis der Operation („Notify on outcome of request (optional)“).</li>\n<li><strong>Datenzugriff</strong>: Die AUTOSAR SW-Component greift unabhängig von der NVRAM-Manager-Direktkommunikation direkt auf den Inhalt der RAM-Blöcke zu („Access content of RAM blocks“).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Entkopplung</strong>: Die Datenübertragung zwischen NVRAM Manager und SW-Component erfolgt nicht über direkte Parameter der Service-Kommunikation, sondern über die dedizierten RAM-Blöcke (RAM Mirror).</li>\n<li><strong>Synchronisation & Exklusivität</strong>: Während der expliziten Übertragungsphase darf die SW-Component nicht konkurrierend auf den betreffenden RAM-Block zugreifen, bis die Operation abgeschlossen ist.</li>\n<li><strong>Konfigurationsverträge</strong>: Zwischen SW-Component und NVRAM Manager müssen Eigenschaften wie Blockgröße, Identifikation und Zugriffsrechte konsistent konfiguriert sein.</li>\n</ul>"}], "trans": [{"from": "FIG-32422ad4e74c2ba1", "to": "FIG-440c8e5a15bd4362", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-440c8e5a15bd4362", "to": "FIG-32422ad4e74c2ba1", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-32422ad4e74c2ba1", "to": "FIG-dc02ee2846558df6", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dc02ee2846558df6", "to": "FIG-d71d614e2e29f4e8", "fr": "R3.2.3", "tr": "R4.0.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Gesamtes Diagramm: Vollständige Beschriftung der linken Interaktionspfeile durch Behebung des Bildabschnitts am linken Rand („Request to restore/save a block from/to non-volatile medium“).</li>\n<li>Gesamtes Diagramm: Wechsel zu einer gerasterten Schwarz-Weiß-Darstellung mit veränderten Bildabmessungen (752x433 Pixel statt 637x433 Pixel).</li>\n</ul>"}]};
